function check([order, s], actual, expected) {
  if (typeof actual !== 'string' || actual.length !== s.length) return false;
  const counts = new Map();
  for (const letter of s) counts.set(letter, (counts.get(letter) ?? 0) + 1);
  for (const letter of actual) {
    if (!counts.get(letter)) return false;
    counts.set(letter, counts.get(letter) - 1);
  }
  let lastRank = -1;
  for (const letter of actual) {
    const rank = order.indexOf(letter);
    if (rank === -1) continue;
    if (rank < lastRank) return false;
    lastRank = rank;
  }
  return true;
}

