function validate([order, s]) {
  if (typeof order !== 'string' || order.length < 1 || order.length > 26) return 'order needs 1 to 26 letters.';
  if (!/^[a-z]+$/.test(order)) return 'order may contain only lowercase English letters.';
  if (new Set(order).size !== order.length) return 'The letters of order must all be different.';
  if (typeof s !== 'string' || s.length < 1 || s.length > 200) return 's needs 1 to 200 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

