function customSortString(order, s) {
  // Give every letter its position in order (unranked letters go last) and sort by it.
  const rank = (letter) => {
    const position = order.indexOf(letter);
    return position === -1 ? 26 : position;
  };
  return s.split('').sort((a, b) => rank(a) - rank(b) || (a < b ? -1 : a > b ? 1 : 0)).join('');
}

