function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.split('');
  const pool = size === 'large' ? 26 : 3 + Math.floor(rand() * 6);
  const letters = alphabet.slice(0, pool);
  for (let i = alphabet.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [alphabet[i], alphabet[j]] = [alphabet[j], alphabet[i]];
  }
  const orderLength = size === 'large' ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * pool);
  // Draw order mostly from the letters s uses, so most of s is ranked.
  const ranked = letters.slice();
  for (let i = ranked.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [ranked[i], ranked[j]] = [ranked[j], ranked[i]];
  }
  const rest = alphabet.filter(letter => !ranked.includes(letter));
  const order = [...ranked, ...rest].slice(0, orderLength).join('');
  const n = size === 'large' ? 200 : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * letters.length)];
  return [order, s];
}
